import {readFileSync} from 'node:fs';
import {baseline,fromIndex,fromContext,withRisk,withRelation,withCase,multi,reorder,field} from './builders.mjs';
export const ASSESSMENT_PACK_VERSION='PRESCORE-CREDIT-ASSESSMENT-RU-GOLDEN-1.0.0';
export function entries(){const es=[];const add=(n,title,input,expected)=>es.push({caseId:`CAS-RU-${String(n).padStart(3,'0')}`,revision:1,title,input,expected:{invariants:true,...expected}});
 add(1,'Healthy complete analytical profile',baseline(),{status:'COMPLETE',confidence:'HIGH',comparable:true,summary:{materialRiskCount:0,otherCreditRiskCount:0},primaryCount:0});
 add(2,'LOW financial risk',fromIndex(2),{requiredDrivers:[{severity:'LOW',dimension:'FINANCIAL_STRENGTH',materiality:'OTHER'}],summary:{otherCreditRiskCount:1}});
 add(3,'MEDIUM financial risk',fromIndex(3),{requiredDrivers:[{severity:'MEDIUM',materiality:'MATERIAL'}]});
 add(4,'HIGH operating risk',withRisk({domain:'CASH_FLOW',severity:'HIGH'}),{requiredDrivers:[{dimension:'OPERATING_BEHAVIOR',severity:'HIGH',finalPenaltyPoints:105}]});
 add(5,'CRITICAL risk',fromIndex(5),{requiredDrivers:[{severity:'CRITICAL',finalPenaltyPoints:240}],indexValue:549});
 add(6,'Financial dimension routing',fromIndex(4),{requiredDrivers:[{dimension:'FINANCIAL_STRENGTH',finalPenaltyPoints:140}]});
 add(7,'Operating dimension routing',fromIndex(6),{requiredDrivers:[{dimension:'OPERATING_BEHAVIOR',finalPenaltyPoints:54}]});
 add(8,'Canonical debt-service override',fromIndex(7),{requiredDrivers:[{riskCode:'RISK-CF-DEBT-SERVICE-BURDEN',domain:'CASH_FLOW',dimension:'DEBT_CREDIT',finalPenaltyPoints:70}],dimensions:[{dimension:'OPERATING_BEHAVIOR',scorePoints:300},{dimension:'DEBT_CREDIT',scorePoints:130}]});
 add(9,'BKI debt dimension',fromIndex('IDX-RU-DEFECT-001'),{requiredDrivers:[{riskCode:'RISK-BKI-CURRENT-OVERDUE',dimension:'DEBT_CREDIT'}]});
 add(10,'Legal credit dimension',fromIndex(10),{requiredDrivers:[{dimension:'LEGAL_CORPORATE',finalPenaltyPoints:35}]});
 add(11,'Multiple risks within capped component',fromIndex(25),{driverCount:4,dimensions:[{dimension:'FINANCIAL_STRENGTH',scorePoints:0}]});
 add(12,'Multiple components',fromIndex(27),{driverCount:4,summary:{materialRiskCount:4}});
 add(13,'Primary ranking by copied Index penalty',fromIndex(27),{primaryCodes:['RISK-FIN-REVENUE-DECLINE','SYN-CASH-HIGH','SYN-FIN-MEDIUM','SYN-LEGAL-MEDIUM']});
 add(14,'Tie breaks by risk code',multi([{id:'z-id',code:'SYN-A'},{id:'a-id',code:'SYN-B'}]),{primaryCodes:['SYN-A','SYN-B']});
 add(15,'All six drivers retained, five primary',multi(Array.from({length:6},(_,n)=>({id:`many-${n}`,code:`SYN-${n}`}))),{driverCount:6,primaryCount:5,primaryCodes:['SYN-0','SYN-1','SYN-2','SYN-3','SYN-4']});
 for(const[n,idx,title]of [[16,11,'Terminated global stop'],[17,12,'Liquidation global stop'],[18,13,'Bankruptcy global stop']])add(n,title,fromIndex(idx),{status:'NOT_RATABLE_GLOBAL_STOP',comparable:false,indexValue:null,requiredDrivers:[{kind:'GLOBAL_STOP',finalPenaltyPoints:null}],summary:{globalStopCount:1}});
 add(19,'Insufficient Index and Readiness',fromIndex(35),{status:'INSUFFICIENT_DATA',indexValue:null,primaryCount:0,requiredLimitations:[{kind:'COVERAGE_LIMITATION'}]});
 add(20,'Partial assessment',fromIndex(34),{status:'PARTIAL',comparable:false,indexValue:1000,requiredLimitations:[{kind:'COVERAGE_LIMITATION'}]});
 add(21,'Missing source data review',fromIndex(15),{status:'PARTIAL',driverCount:0,requiredLimitations:[{sourceCode:'SOURCE-MISSING'}]});
 add(22,'Stale BKI limitation',fromContext(17),{requiredLimitations:[{kind:'CONTEXT_REVIEW',sourceCode:'CTX-BKI-STALE'}],forbiddenDrivers:[{riskCode:'RISK-BKI-CURRENT-OVERDUE'}]});
 add(23,'Reconciliation conflict',fromContext(19),{requiredLimitations:[{sourceCode:'CTX-RECON-CONFLICT'}],driverCount:0});
 add(24,'Missing bank period',fromContext(21),{status:'INSUFFICIENT_DATA',requiredLimitations:[{sourceCode:'CTX-BANK-COVERAGE'}]});
 add(25,'Exact mitigation linkage',fromIndex(20),{requiredContext:[{effect:'MITIGATES',targetRiskCode:'RISK-FIN-REVENUE-DECLINE'}],requiredDrivers:[{riskCode:'RISK-FIN-REVENUE-DECLINE',finalPenaltyPoints:126}],indexValue:679});
 add(26,'Exact corroboration linkage',fromIndex(18),{requiredContext:[{effect:'CORROBORATES',targetRiskCode:'RISK-FIN-REVENUE-DECLINE'}],requiredDrivers:[{riskCode:'RISK-FIN-REVENUE-DECLINE',finalPenaltyPoints:154}],indexValue:651});
 add(27,'Explanation is not numeric adjustment',fromIndex(22),{requiredContext:[{effect:'EXPLAINS',targetRiskCode:'RISK-FIN-REVENUE-DECLINE'}],indexValue:665});
 add(28,'Context review limitation',withRelation('REQUIRES_REVIEW'),{requiredLimitations:[{kind:'CONTEXT_REVIEW',sourceCode:'SYN-CONTEXT-synthetic-context'}]});
 for(const[n,ctx,title]of [[29,24,'Company age neutral'],[30,25,'OKVED neutral'],[31,26,'Region neutral']])add(n,title,fromContext(ctx),{driverCount:0,requiredContext:[{effect:'NEUTRAL',code:'CTX-BUSINESS-PROFILE'}]});
 add(32,'Marketplace model explanation',fromContext(8),{requiredContext:[{effect:'EXPLAINS',code:'CTX-MARKETPLACE-MODEL'}],forbiddenDrivers:[{riskCode:'RISK-CF-CUSTOMER-CONCENTRATION'}]});
 add(33,'Contract-backed concentration keeps risk',fromContext(7),{requiredContext:[{effect:'EXPLAINS',code:'CTX-CONCENTRATION-CONTRACT',targetRiskCode:'RISK-CF-CUSTOMER-CONCENTRATION'}],requiredDrivers:[{riskCode:'RISK-CF-CUSTOMER-CONCENTRATION'}]});
 add(34,'Client seasonality declaration is explanation',fromContext(29),{requiredContext:[{effect:'EXPLAINS',code:'CTX-CASE-EXPLANATION'}],summary:{mitigatingContextCount:0}});
 add(35,'No financing case',baseline(),{caseDefinitionStatus:'NOT_PROVIDED',relative:[{other:'CAS-RU-037',field:'drivers',operator:'EQ'}]});
 add(36,'Partial financing case',withCase({requestedTermMonths:field(null)}),{caseDefinitionStatus:'PARTIAL',driverCount:0});
 add(37,'Defined financing case',withCase(),{caseDefinitionStatus:'DEFINED',driverCount:0});
 add(38,'Billion-ruble request is context only',withCase({requestedAmount:field(1000000000)}),{caseDefinitionStatus:'DEFINED',relative:[{other:'CAS-RU-037',field:'drivers',operator:'EQ'},{other:'CAS-RU-037',field:'status',operator:'EQ'}]});
 add(39,'Requested overdraft is not recommendation',withCase({requestedProduct:field('OVERDRAFT')}),{relative:[{other:'CAS-RU-037',field:'drivers',operator:'EQ'}]});
 add(40,'Personal BKI not company debt',fromIndex(31),{driverCount:0});
 add(41,'Guarantorship remains contingent',fromIndex(32),{driverCount:0,requiredContext:[{effect:'NEUTRAL',code:'CTX-CONTINGENT-GUARANTORSHIP'}]});
 add(42,'Bank guarantee remains contingent',fromIndex(33),{driverCount:0,requiredContext:[{effect:'NEUTRAL',code:'CTX-CONTINGENT-BANK-GUARANTEE'}]});
 add(43,'Current overdue and historical zero',fromIndex('IDX-RU-DEFECT-001'),{defect:true,requiredDrivers:[{riskCode:'RISK-BKI-CURRENT-OVERDUE',severity:'MEDIUM'}],forbiddenDrivers:[{riskCode:'RISK-BKI-HISTORICAL-DELINQUENCY'}]});
 add(44,'Input reordering byte identical',reorder(fromIndex(40)),{relative:[{other:'CAS-RU-045',field:'output',operator:'EQ'}]});
 add(45,'Real canonical multi-risk pipeline',fromIndex(40),{status:'PARTIAL',requiredDrivers:[{riskCode:'RISK-FIN-REVENUE-DECLINE'},{riskCode:'RISK-CF-CUSTOMER-CONCENTRATION'}]});
 es.push({caseId:'CAS-RU-DEFECT-001',revision:1,title:'Permanent five-block historical-zero overdue chain',input:fromIndex('IDX-RU-DEFECT-001'),expected:{invariants:true,defect:true,requiredDrivers:[{riskCode:'RISK-BKI-CURRENT-OVERDUE',severity:'MEDIUM'}],forbiddenDrivers:[{riskCode:'RISK-BKI-HISTORICAL-DELINQUENCY'}]}});return es;}
export function loadAssessmentPack(){return {version:ASSESSMENT_PACK_VERSION,entries:entries(),fingerprints:JSON.parse(readFileSync(new URL('./fingerprints-stage5.json',import.meta.url),'utf8'))};}
